// Confirmed resource detail composition. Data/operations stay with the existing
// prototype adapters; no production requests or financial records are written.
const rdPreviousCategory=dCategoryDetail,rdPreviousAccount=dAccountDetail;
let rdDraft=null;
Object.assign(state,{rdSort:'timeDesc'});let rdFlowDraft=null;
const rdSortNames={timeDesc:'时间↓',timeAsc:'时间↑',amountDesc:'金额↓',amountAsc:'金额↑'};
function rdSortRows(a,b){const order=state.rdSort||'timeDesc',value=order.startsWith('amount')?a.amount-b.amount:(a.rdDate+' '+(a.time||'')).localeCompare(b.rdDate+' '+(b.time||''));return order.endsWith('Asc')?value:-value;}

function rdButton(action,contents,label,cls='',attrs=''){return btn('rd-control',contents,label,cls,attrs).replace('data-action="rd-control"',`data-rd="${action}"`);}
function rdMenu(action,ico,title){return menuRow('rd-control',ico,title).replace('data-action="rd-control"',`data-rd="${action}"`);}

function rdPeriod(kind){return kind==='category'?dc97Active?.period||state.dPeriod||'all':state.adDetailPeriod||'month';}
function rdAnchor(kind){return kind==='category'?dc97Active?.anchor||`${state.year||2026}-${String(state.month||10).padStart(2,'0')}`:state.adDetailAnchor||'2026-10';}
function rdControls(kind){const period=rdPeriod(kind),[year,month]=rdAnchor(kind).split('-').map(Number);return `<div class="rd-period-controls"><nav class="rd-period" role="tablist">${[['month','月'],['year','年'],['all','全部']].map(([id,label])=>`<button type="button" data-rd="period:${kind}:${id}" role="tab" aria-selected="${period===id}">${label}</button>`).join('')}</nav><div class="rd-range" ${kind==='category'&&period==='all'?'hidden':''}>${period==='all'?'':`<button data-rd="step:${kind}:-1" aria-label="上一周期">${icon('chevron-left')}</button>`}<button data-rd="date:${kind}" class="rd-range-label">${icon('calendar-days')}<span>${period==='all'?'全部时间':period==='year'?year+' 年':year+' 年 '+month+' 月'}</span>${icon('chevron-down')}</button>${period==='all'?'<small>所有记录</small>':`<button data-rd="step:${kind}:1" aria-label="下一周期">${icon('chevron-right')}</button>`}</div></div>`;}
dCategoryDetail=function(){const template=document.createElement('template');template.innerHTML=rdPreviousCategory();const detail=template.content.querySelector('.dc97-detail');if(!detail)return template.innerHTML;detail.classList.add('rd-category-detail');const period=detail.querySelector('.dc97-period'),date=detail.querySelector('.dc97-date');period?.insertAdjacentHTML('beforebegin',rdControls('category'));period?.remove();date?.remove();const parent=detail.querySelector('.dc97-parent'),hero=detail.querySelector('.dc97-hero');if(parent&&hero){parent.classList.add('rd-parent');parent.innerHTML=`${icon('corner-up-left')}<small>上级</small><span>${esc(dc97Active?.category||'餐饮')}</span>${icon('chevron-right')}`;hero.prepend(parent);const caption=hero.querySelector('.dc97-identity small');if(caption)caption.textContent='二级分类 · '+(dc97Active?.scope==='all'?'全部账本':dc97Active?.books.find(b=>b.id===dc97Active.target)?.name||state.ledger);}return template.innerHTML;};
function rdAccountRows(a){const values=state.adScenario==='empty'?[]:state.adScenario?[{id:9001,title:'周末采购',category:'购物',amount:168,type:'expense',account:a.name,day:24,time:'12:34',currency:a.currency},{id:9002,title:a.type==='credit_card'?'信用卡还款':'账户转入',category:'转账',amount:500,type:'transfer',direction:'in',account:a.name,day:23,time:'18:20',currency:a.currency},{id:9003,title:'午间食堂',category:'餐饮',amount:32,type:'expense',account:a.name,day:22,time:'12:10',currency:a.currency}]:dRows().filter(r=>r.account===a.name);return values.map(r=>({...r,rdDate:`${r.year||2026}-${String(r.month||10).padStart(2,'0')}-${String(r.day||1).padStart(2,'0')}`}));}
function rdInRange(row){const p=rdPeriod('account'),anchor=rdAnchor('account');return p==='all'||row.rdDate.startsWith(p==='year'?anchor.slice(0,4):anchor);}
function rdDelta(row){return row.type==='income'||row.type==='transfer'&&row.direction==='in'?row.amount:-row.amount;}
function rdAccountTrend(a,all){let balance=a.amount-all.reduce((sum,r)=>sum+rdDelta(r),0);const points=[...all].sort((x,y)=>x.rdDate.localeCompare(y.rdDate)).map(r=>({date:r.rdDate,value:balance+=rdDelta(r)})).filter(p=>rdInRange({rdDate:p.date}));if(!points.length||state.hide)return `<section class="bc-surface rd-balance"><h3>余额趋势</h3><p class="rd-empty">${state.hide?'金额已隐藏':'当前范围暂无历史记录'}</p></section>`;const values=points.map(p=>p.value),lo=Math.min(...values),hi=Math.max(...values),span=hi-lo||1,coords=points.map((p,i)=>({x:10+(points.length===1?.5:i/(points.length-1))*280,y:106-(p.value-lo)/span*80,...p})),line=coords.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ');return `<section class="bc-surface rd-balance"><div class="bc-between"><h3>余额趋势</h3><small>${esc(a.currency||'CNY')}</small></div><p class="rd-balance-caption" data-rd-balance-caption>期末余额 ${vSymbol(a.currency)}${money(points.at(-1).value)}</p><svg class="rd-balance-svg" viewBox="0 0 300 126" role="img" aria-label="余额历史"><path class="rd-grid" d="M0 26H300M0 66H300M0 106H300"/><path class="rd-area" d="${line}L${coords.at(-1).x},116L${coords[0].x},116Z"/><path class="rd-line" d="${line}"/>${coords.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="3"/><circle class="rd-point-hit" cx="${p.x}" cy="${p.y}" r="12" data-rd="point" data-rd-caption="${p.date} · ${vSymbol(a.currency)}${money(p.value)}" role="button" tabindex="0"/>`).join('')}</svg><div class="rd-axis"><span>${points[0].date}</span><span>${points.at(-1).date}</span></div></section>`;}
dAccountDetail=function(){const original=rdPreviousAccount(),source=adAccount(),a={...source,currency:source.currency||'CNY',amount:state.adValue!==''?Number(state.adValue):source.amount},type=a.type||avType(a),valuation=aEditorTypes.find(t=>t[0]===type)?.[2]==='valuation',credit=type==='credit_card';const template=document.createElement('template');template.innerHTML=original;const hero=template.content.querySelector('.d-hero');if(!hero)return original;hero.classList.add('rd-account-summary');const metrics=hero.querySelector('.d-hero-stats');const propertyHtml=`<div class="d-hero-stats rd-properties">${dMetric('计入净资产','已计入')}${rdButton('ledgers',`<small>关联账本</small><strong>${new Set(rdAccountRows(a).map(row=>row.ledger||state.ledger)).size} 个账本 ${icon('chevron-right')}</strong>`,'查看关联账本','rd-property')}</div>`;if(metrics)metrics.outerHTML=propertyHtml;else hero.insertAdjacentHTML('beforeend',propertyHtml);const heading=template.content.querySelector('.bc-subhead');const menu=heading?.querySelector('[data-action=ad-edit]');if(menu){delete menu.dataset.action;menu.dataset.rd='menu';menu.innerHTML=icon('ellipsis');menu.setAttribute('aria-label','账户操作');}if(valuation)return `<div class="rd-account">${template.innerHTML}</div>`;const all=rdAccountRows(a),rows=all.filter(rdInRange),incoming=rows.filter(r=>rdDelta(r)>0&&!r.excludeStats).reduce((n,r)=>n+r.amount,0),outgoing=rows.filter(r=>rdDelta(r)<0&&!r.excludeStats).reduce((n,r)=>n+r.amount,0),shown=rows.filter(r=>(state.dFlow==='all'||(state.dFlow==='income'?rdDelta(r)>0:rdDelta(r)<0))&&(!state.adDetailQuery||[r.title,r.category,r.ledger||state.ledger].some(value=>String(value||'').includes(state.adDetailQuery)))).sort(rdSortRows),sym=vSymbol(a.currency),display=n=>state.hide?'••••':sym+money(n);const terms=template.content.querySelector('.ad-credit-terms');return `<div class="rd-account">${heading?.outerHTML||subhead('账户详情','ad-edit','pencil-line')}${hero.outerHTML}<div class="d-primary-actions rd-primary-actions">${btn('ad-repay',`${icon('arrow-left-right')}${credit?'还款':'转账'}`,credit?'还款':'转账','bc-secondary')}${rdButton('record',`${icon('plus')}记一笔`,'记一笔','bc-primary')}</div>${terms?.outerHTML||''}${rdControls('account')}<section class="bc-surface rd-cashflow"><div class="bc-between"><h3>账户收支 <small>${esc(a.currency||'CNY')}</small></h3><button data-rd="distribution">分类占比 ${icon('chevron-right')}</button></div><div class="d-hero-stats">${dMetric('收入',display(incoming))}${dMetric('支出',display(outgoing))}${dMetric('净流入',display(incoming-outgoing))}</div></section>${rdAccountTrend(a,all)}<div class="rd-flow-bar"><h3>交易记录</h3><div class="rd-transaction-actions">${rdButton('search',icon('search'),'搜索账户交易')}${rdButton('flows',icon('sliders-horizontal'),'筛选交易记录')}</div></div>${true?`<div class="rd-applied-filters">${rdButton('flows',`<span>${icon('arrow-down-up')}排序 · ${rdSortNames[state.rdSort||'timeDesc']}</span>`,'选择排序方式','rd-applied-chip rd-sort-chip')}${state.adDetailQuery?rdButton('clear-query',`<span>${icon('check')}${esc(state.adDetailQuery)}</span>`,'清除搜索','rd-applied-chip'):''}${state.dFlow!=='all'?rdButton('clear-flow',`<span>${icon('check')}${state.dFlow==='income'?'收入与转入':'支出与转出'}</span>`,'清除流向筛选','rd-applied-chip'):''}</div>`:''}<div class="bc-surface c3-consumer-list">${shown.length?shown.map(r=>cAccountTransaction(r,a)).join(''):'<p class="rd-empty">暂无交易记录</p>'}</div></div>`;};
function rdWheel(column,values,selected,suffix){return `<div class="rd-wheel" data-rd-wheel="${column}" tabindex="0" role="spinbutton" aria-label="${column==='year'?'年份':'月份'}"><div>${values.map(v=>`<button data-rd="wheel:${column}:${v}" aria-selected="${v===selected}">${v}${suffix}</button>`).join('')}</div></div>`;}
function rdDateSheet(){sheet('选择统计时间',`<div class="rd-picker"><nav class="rd-period" role="tablist">${[['month','月'],['year','年'],['all','全部']].map(([v,label])=>`<button data-rd="draft:${v}" aria-selected="${rdDraft.period===v}">${label}</button>`).join('')}</nav>${rdDraft.period==='all'?'<p class="rd-empty">查看全部历史记录</p>':`<div class="rd-wheels"><span class="rd-wheel-highlight"></span>${rdWheel('year',Array.from({length:101},(_,i)=>i+2000),rdDraft.year,' 年')}${rdDraft.period==='month'?rdWheel('month',Array.from({length:12},(_,i)=>i+1),rdDraft.month,' 月'):''}</div>`}<button class="bc-primary" data-rd="apply">确认</button></div>`);for(const el of phone.querySelectorAll('[data-rd-wheel]')){const k=el.dataset.rdWheel,min=k==='year'?2000:1;el.scrollTop=(rdDraft[k]-min)*36;el.addEventListener('scroll',()=>{if(!rdDraft)return;rdDraft[k]=Math.max(min,Math.min(k==='year'?2100:12,Math.round(el.scrollTop/36)+min));});}}
function rdSetPeriod(kind,period,anchor=rdAnchor(kind)){if(kind==='category'){if(dc97Active){dc97Active.period=period;dc97Active.anchor=anchor;}state.dPeriod=period;}else{state.adDetailPeriod=period;state.adDetailAnchor=anchor;}render();}
root.addEventListener('click',event=>{const target=event.target.closest('[data-rd]');if(target){event.preventDefault();event.stopImmediatePropagation();const [action,kind,value]=target.dataset.rd.split(':');if(action==='period')return rdSetPeriod(kind,value);if(action==='clear-query'){state.adDetailQuery='';return render();}if(action==='clear-flow'){state.dFlow='all';return render();}if(action==='menu')return sheet('账户操作',menuRow('ad-edit','pencil-line','编辑账户')+rdMenu('search','search','搜索账户流水')+rdMenu('ledgers','book-open','关联账本')+rdMenu('hide','eye-off','隐藏账户')+rdMenu('delete','trash-2','删除账户'));if(action==='search')return sheet('搜索账户流水',`<label class="form-label">备注、分类或账本<input class="form-input" data-rd-query value="${esc(state.adDetailQuery||'')}"></label><button class="bc-primary" data-rd="search-apply">应用</button>`);if(action==='ledgers')return sheet('关联账本',`<p class="bc-small">账户跨账本使用，以下为已有记录的关联账本。</p>${menuRow('close','book-open',state.ledger,'当前账本')}`);if(action==='record'){state.recordAccount=adAccount().name;state.recordType='expense';state.fRecordCurrency=adAccount().currency;return navigate('editor');}if(action==='hide'||action==='delete'){closeSheet();const trigger=document.createElement('button');trigger.dataset.action='ad-edit';root.appendChild(trigger);trigger.click();trigger.remove();requestAnimationFrame(()=>phone.querySelector('[data-action="'+(action==='hide'?'ae-hide':'ae-delete')+'"]')?.click());return;}if(action==='date'){const [year,month]=rdAnchor(kind).split('-').map(Number);rdDraft={kind,year,month,period:rdPeriod(kind)};return rdDateSheet();}if(action==='step'){const [year,month]=rdAnchor(kind).split('-').map(Number),period=rdPeriod(kind),date=new Date(period==='year'?year+Number(value):year,period==='month'?month-1+Number(value):month-1,1);return rdSetPeriod(kind,period,`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}`);}if(action==='draft'){rdDraft.period=kind;return rdDateSheet();}if(action==='wheel'){const el=phone.querySelector(`[data-rd-wheel="${kind}"]`);el.scrollTop=(Number(value)-(kind==='year'?2000:1))*36;return;}if(action==='apply'){const draft=rdDraft;rdDraft=null;closeSheet();return rdSetPeriod(draft.kind,draft.period,`${draft.year}-${String(draft.month).padStart(2,'0')}`);}if(action==='point'){phone.querySelector('[data-rd-balance-caption]').textContent=target.dataset.rdCaption;return;}if(action==='distribution')return sheet('分类占比',adDistribution(adAccount(),rdAccountRows(adAccount())));if(action==='search-apply'){state.adDetailQuery=phone.querySelector('[data-rd-query]').value.trim();closeSheet();return render();}if(action==='flow-choice'){rdFlowDraft.flow=kind;phone.querySelectorAll('[data-rd^="flow-choice:"]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.rd==='flow-choice:'+kind)));return;}if(action==='flows-apply'){state.dFlow=rdFlowDraft.flow;state.rdSort=phone.querySelector('[data-rd-sort-draft]').value;closeSheet();return render();}if(action==='flows'){rdFlowDraft={flow:state.dFlow,sort:state.rdSort||'timeDesc'};return sheet('筛选账户流水',`<nav class="rd-period rd-flow-options">${[['all','全部流水'],['expense','支出与转出'],['income','收入与转入']].map(([v,label])=>rdButton('flow-choice:'+v,label,label,'',`aria-selected="${v===state.dFlow}"`)).join('')}</nav><label class="rd-flow-sort">排序<select data-rd-sort-draft style="display:block;width:100%;margin-top:8px">${Object.entries(rdSortNames).map(([value,label])=>`<option value="${value}" ${value===rdFlowDraft.sort?'selected':''}>${label}</option>`).join('')}</select></label><button class="bc-primary" data-rd="flows-apply" style="width:100%;margin-top:16px">确认</button>`);} }
},true);
